import { Tooltip, TooltipTrigger, TooltipContent, TooltipProvider } from "@nativecn/ui/components/tooltip";
import { Button } from "@nativecn/ui/components/button";

export default function App() {
  return (
    <TooltipProvider>
      <Tooltip>
        <TooltipTrigger>
          <Button variant="outline">Hover me</Button>
        </TooltipTrigger>
        <TooltipContent>
          Add to your saved items
        </TooltipContent>
      </Tooltip>
    </TooltipProvider>
  );
}
